import {
  Group,
  PlaneGeometry,
  Mesh,
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
  Color,
  SRGBColorSpace,
  ClampToEdgeWrapping,
  FrontSide,
} from 'three/webgpu';
import { vec3, mix, uv, smoothstep, abs } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // ------------------------------------------------------------
  // 1. Resolve visuals & content
  // ------------------------------------------------------------
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headline = items.find((item) => item.role === 'headline');
  const labelText = headline?.text ?? 'Pricing 1';
  const labelFontSize = headline?.typography?.fontSize ?? 39;
  const labelColor = headline?.color ?? colors.paper;

  const colorInk = new Color(colors.ink);
  const colorPaper = new Color(colors.paper);
  const colorSurface = new Color(colors.surface);
  const colorAccent = new Color(colors.accent);

  // ------------------------------------------------------------
  // 2. Build label background plane (engineered gradient surface)
  // ------------------------------------------------------------
  const labelGeometry = new PlaneGeometry(1.8, 0.5);
  const labelMaterial = new MeshStandardNodeMaterial();
  labelMaterial.side = FrontSide;
  labelMaterial.roughness = 0.5;
  labelMaterial.metalness = 0.25;
  labelMaterial.color.set(colors.surface);

  // Subtle vertical gradient: surface -> ink
  const uvNode = uv();
  const gradient = mix(vec3(colorSurface), vec3(colorInk), uvNode.y);

  // Accent line embedded in the gradient (engineered detail)
  const accentLineMask = smoothstep(0.03, 0.0, abs(uvNode.y - 0.85));
  const accentLineColor = vec3(colorAccent);
  labelMaterial.colorNode = mix(gradient, accentLineColor, accentLineMask);

  const labelMesh = new Mesh(labelGeometry, labelMaterial);
  labelMesh.position.set(0, 0, 0);
  group.add(labelMesh);

  // ------------------------------------------------------------
  // 3. Decorative orb texture (loaded async)
  // ------------------------------------------------------------
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = SRGBColorSpace;
      tex.wrapS = ClampToEdgeWrapping;
      tex.wrapT = ClampToEdgeWrapping;
      labelMaterial.map = tex;
      // Map multiplies with the colorNode – the dark surface will tone it down
      labelMaterial.needsUpdate = true;
    });
  }

  // ------------------------------------------------------------
  // 4. Accent line (physical 3D edge detail)
  // ------------------------------------------------------------
  const borderGeometry = new PlaneGeometry(1.6, 0.025);
  const borderMaterial = new MeshBasicNodeMaterial();
  borderMaterial.colorNode = vec3(colorAccent);
  const borderMesh = new Mesh(borderGeometry, borderMaterial);
  borderMesh.position.set(0, -0.2, 0.015);
  group.add(borderMesh);

  // ------------------------------------------------------------
  // 5. Headline text via MSDF atlas
  // ------------------------------------------------------------
  const textMesh = ctx.fontAtlas.createText(labelText, {
    fontSize: labelFontSize,
    color: labelColor,
    align: 'left',
    letterSpacingPx: 2,
  });
  textMesh.position.set(-0.7, 0.04, 0.01);
  group.add(textMesh);

  // ------------------------------------------------------------
  // 6. Handlers & cleanup (no interactivity specified)
  // ------------------------------------------------------------
  group.userData.handlers = {};

  group.userData.cleanup = () => {
    labelGeometry.dispose();
    labelMaterial.dispose();
    borderGeometry.dispose();
    borderMaterial.dispose();
    if (labelMaterial.map) labelMaterial.map.dispose();
    // No gsap timelines to kill
  };

  return group;
}
